        { intrebare: "5. Ce face societatea civilă când o decizie a statului încălca drepturile?", raspunsuri: ["Contestă decizia autorităților", "O ignoră", "Sărbătorește"], corect: 0 },
        { intrebare: "6. Care ONG din România este membru al 'Save the Children International'?", raspunsuri: ["'Salvați Copiii' România", "Clubul de șah", "Crucea Roșie"], corect: 0 },
        { intrebare: "7. În ce domenii pot activa ONG-urile?", raspunsuri: ["Mediu, sănătate, animale, drepturile copilului", "Doar în sport", "Doar în politică"], corect: 0 },
        { intrebare: "8. De ce sunt utile ONG-urile pentru cetățeni?", raspunsuri: ["Oferă soluții noi și sprijină comunitățile", "Cresc impozitele", "Măresc numărul de ore"], corect: 0 }
